import { I18nProvider, useTaleI18n } from '@tale-ui/react/i18n-provider';
import { Text } from '@tale-ui/react/text';

function PageStatus() {
  const { formatMessage } = useTaleI18n();
  return <Text>{formatMessage('table.page', { page: 2, pageCount: 8 })}</Text>;
}

export function PseudoLocalePreview() {
  return (
    <I18nProvider mode="pseudo">
      <PageStatus />
    </I18nProvider>
  );
}
